{
  "ok": true,
  "tool": "list_operations",
  "operations": [
    {
      "op": "add_angular_dim",
      "category": "annotate",
      "description": "Angular dimension from vertex 'center' between rays to p1 and p2 (measured CCW from p1 to p2); 'radius' places the dimension arc.",
      "params": {
        "type": "object",
        "properties": {
          "center": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": " [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "p1": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": " [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "p2": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": " [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "radius": {
            "type": [
              "number",
              "string"
            ],
            "description": "Radius of the dimension arc (default: 0.6 x shorter ray) (drawing units, or string with unit e.g. '8mm')",
            "exclusiveMinimum": 0
          },
          "text": {
            "type": "string",
            "description": "Text override; '<>' stands for the measured value"
          },
          "text_height": {
            "type": [
              "number",
              "string"
            ],
            "description": "Override text height (drawing units, or string with unit e.g. '8mm')",
            "exclusiveMinimum": 0
          },
          "layer": {
            "type": "string",
            "description": "Layer name (created on the fly if missing)"
          },
          "color": {
            "type": "integer",
            "description": "ACI color (256 = BYLAYER)",
            "minimum": 0,
            "maximum": 257
          },
          "linetype": {
            "type": "string",
            "description": "Linetype name, e.g. CONTINUOUS, CENTER, DASHED"
          },
          "lineweight": {
            "type": "integer",
            "description": "Lineweight in 1/100 mm (e.g. 50 = 0.50 mm), -1 = BYLAYER"
          },
          "tag": {
            "type": "string",
            "description": "Semantic tag for later reference as 'tag:<name>'"
          },
          "if_tag_exists": {
            "type": "string",
            "enum": [
              "error",
              "skip",
              "replace"
            ],
            "description": "Behaviour when an entity with this tag already exists (use 'skip' for idempotent replays)",
            "default": "error"
          }
        },
        "required": [
          "center",
          "p1",
          "p2"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "add_arc",
      "category": "draw",
      "description": "Draw a circular arc, counter-clockwise from start_angle to end_angle (degrees). Alternatively give three points 'start', 'mid', 'end' on the arc.",
      "params": {
        "type": "object",
        "properties": {
          "center": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Center [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "radius": {
            "type": [
              "number",
              "string"
            ],
            "description": "Radius (drawing units, or string with unit e.g. '8mm')",
            "exclusiveMinimum": 0
          },
          "start_angle": {
            "type": "number",
            "description": "Start angle (degrees, counter-clockwise)"
          },
          "end_angle": {
            "type": "number",
            "description": "End angle (degrees, counter-clockwise)"
          },
          "start": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "3-point form: start point [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "mid": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "3-point form: point on arc [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "end": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "3-point form: end point [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "layer": {
            "type": "string",
            "description": "Layer name (created on the fly if missing)"
          },
          "color": {
            "type": "integer",
            "description": "ACI color (256 = BYLAYER)",
            "minimum": 0,
            "maximum": 257
          },
          "linetype": {
            "type": "string",
            "description": "Linetype name, e.g. CONTINUOUS, CENTER, DASHED"
          },
          "lineweight": {
            "type": "integer",
            "description": "Lineweight in 1/100 mm (e.g. 50 = 0.50 mm), -1 = BYLAYER"
          },
          "tag": {
            "type": "string",
            "description": "Semantic tag for later reference as 'tag:<name>'"
          },
          "if_tag_exists": {
            "type": "string",
            "enum": [
              "error",
              "skip",
              "replace"
            ],
            "description": "Behaviour when an entity with this tag already exists (use 'skip' for idempotent replays)",
            "default": "error"
          }
        },
        "required": [],
        "additionalProperties": false
      }
    },
    {
      "op": "add_circle",
      "category": "draw",
      "description": "Draw a circle. Give 'radius' or 'diameter'.",
      "params": {
        "type": "object",
        "properties": {
          "center": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Center [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "radius": {
            "type": [
              "number",
              "string"
            ],
            "description": "Radius (drawing units, or string with unit e.g. '8mm')",
            "exclusiveMinimum": 0
          },
          "diameter": {
            "type": [
              "number",
              "string"
            ],
            "description": "Diameter (drawing units, or string with unit e.g. '8mm')",
            "exclusiveMinimum": 0
          },
          "layer": {
            "type": "string",
            "description": "Layer name (created on the fly if missing)"
          },
          "color": {
            "type": "integer",
            "description": "ACI color (256 = BYLAYER)",
            "minimum": 0,
            "maximum": 257
          },
          "linetype": {
            "type": "string",
            "description": "Linetype name, e.g. CONTINUOUS, CENTER, DASHED"
          },
          "lineweight": {
            "type": "integer",
            "description": "Lineweight in 1/100 mm (e.g. 50 = 0.50 mm), -1 = BYLAYER"
          },
          "tag": {
            "type": "string",
            "description": "Semantic tag for later reference as 'tag:<name>'"
          },
          "if_tag_exists": {
            "type": "string",
            "enum": [
              "error",
              "skip",
              "replace"
            ],
            "description": "Behaviour when an entity with this tag already exists (use 'skip' for idempotent replays)",
            "default": "error"
          }
        },
        "required": [
          "center"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "add_diameter_dim",
      "category": "annotate",
      "description": "Diameter dimension of a circle/arc.",
      "params": {
        "type": "object",
        "properties": {
          "target": {
            "description": "CIRCLE or ARC to dimension — entity selector: handle id, 'tag:<name>', '$<op index>', a list of these, or a filter object {type, layer, tag, tag_prefix}"
          },
          "center": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": " [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "radius": {
            "type": [
              "number",
              "string"
            ],
            "description": " (drawing units, or string with unit e.g. '8mm')",
            "exclusiveMinimum": 0
          },
          "angle": {
            "type": "number",
            "description": "Direction of the leader (degrees, counter-clockwise)",
            "default": 45.0
          },
          "text": {
            "type": "string",
            "description": "Text override; '<>' stands for the measured value"
          },
          "text_height": {
            "type": [
              "number",
              "string"
            ],
            "description": "Override text height (drawing units, or string with unit e.g. '8mm')",
            "exclusiveMinimum": 0
          },
          "layer": {
            "type": "string",
            "description": "Layer name (created on the fly if missing)"
          },
          "color": {
            "type": "integer",
            "description": "ACI color (256 = BYLAYER)",
            "minimum": 0,
            "maximum": 257
          },
          "linetype": {
            "type": "string",
            "description": "Linetype name, e.g. CONTINUOUS, CENTER, DASHED"
          },
          "lineweight": {
            "type": "integer",
            "description": "Lineweight in 1/100 mm (e.g. 50 = 0.50 mm), -1 = BYLAYER"
          },
          "tag": {
            "type": "string",
            "description": "Semantic tag for later reference as 'tag:<name>'"
          },
          "if_tag_exists": {
            "type": "string",
            "enum": [
              "error",
              "skip",
              "replace"
            ],
            "description": "Behaviour when an entity with this tag already exists (use 'skip' for idempotent replays)",
            "default": "error"
          }
        },
        "required": [],
        "additionalProperties": false
      }
    },
    {
      "op": "add_ellipse",
      "category": "draw",
      "description": "Draw an ellipse (or elliptical arc) by semi-axes rx, ry and rotation.",
      "params": {
        "type": "object",
        "properties": {
          "center": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Center [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "rx": {
            "type": [
              "number",
              "string"
            ],
            "description": "Semi-axis along the rotated X (drawing units, or string with unit e.g. '8mm')",
            "exclusiveMinimum": 0
          },
          "ry": {
            "type": [
              "number",
              "string"
            ],
            "description": "Semi-axis along the rotated Y (drawing units, or string with unit e.g. '8mm')",
            "exclusiveMinimum": 0
          },
          "rotation": {
            "type": "number",
            "description": "Rotation of the rx axis (degrees, counter-clockwise)",
            "default": 0.0
          },
          "start_angle": {
            "type": "number",
            "description": "Start parameter angle (degrees, counter-clockwise)",
            "default": 0.0
          },
          "end_angle": {
            "type": "number",
            "description": "End parameter angle (degrees, counter-clockwise)",
            "default": 360.0
          },
          "layer": {
            "type": "string",
            "description": "Layer name (created on the fly if missing)"
          },
          "color": {
            "type": "integer",
            "description": "ACI color (256 = BYLAYER)",
            "minimum": 0,
            "maximum": 257
          },
          "linetype": {
            "type": "string",
            "description": "Linetype name, e.g. CONTINUOUS, CENTER, DASHED"
          },
          "lineweight": {
            "type": "integer",
            "description": "Lineweight in 1/100 mm (e.g. 50 = 0.50 mm), -1 = BYLAYER"
          },
          "tag": {
            "type": "string",
            "description": "Semantic tag for later reference as 'tag:<name>'"
          },
          "if_tag_exists": {
            "type": "string",
            "enum": [
              "error",
              "skip",
              "replace"
            ],
            "description": "Behaviour when an entity with this tag already exists (use 'skip' for idempotent replays)",
            "default": "error"
          }
        },
        "required": [
          "center",
          "rx",
          "ry"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "add_leader",
      "category": "annotate",
      "description": "Leader (arrow polyline) with an MTEXT note at the last vertex.",
      "params": {
        "type": "object",
        "properties": {
          "points": {
            "type": "array",
            "items": {
              "type": "array"
            },
            "description": "Leader vertices, arrow at the first point list of [x, y] (or [x, y, bulge]) (drawing units, or string with unit e.g. '8mm')"
          },
          "text": {
            "type": "string",
            "description": ""
          },
          "text_height": {
            "type": [
              "number",
              "string"
            ],
            "description": " (drawing units, or string with unit e.g. '8mm')",
            "exclusiveMinimum": 0,
            "default": 2.5
          },
          "layer": {
            "type": "string",
            "description": "Layer name (created on the fly if missing)"
          },
          "color": {
            "type": "integer",
            "description": "ACI color (256 = BYLAYER)",
            "minimum": 0,
            "maximum": 257
          },
          "linetype": {
            "type": "string",
            "description": "Linetype name, e.g. CONTINUOUS, CENTER, DASHED"
          },
          "lineweight": {
            "type": "integer",
            "description": "Lineweight in 1/100 mm (e.g. 50 = 0.50 mm), -1 = BYLAYER"
          },
          "tag": {
            "type": "string",
            "description": "Semantic tag for later reference as 'tag:<name>'"
          },
          "if_tag_exists": {
            "type": "string",
            "enum": [
              "error",
              "skip",
              "replace"
            ],
            "description": "Behaviour when an entity with this tag already exists (use 'skip' for idempotent replays)",
            "default": "error"
          }
        },
        "required": [
          "points",
          "text"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "add_line",
      "category": "draw",
      "description": "Draw a straight line segment.",
      "params": {
        "type": "object",
        "properties": {
          "start": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Start point [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "end": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "End point [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "layer": {
            "type": "string",
            "description": "Layer name (created on the fly if missing)"
          },
          "color": {
            "type": "integer",
            "description": "ACI color (256 = BYLAYER)",
            "minimum": 0,
            "maximum": 257
          },
          "linetype": {
            "type": "string",
            "description": "Linetype name, e.g. CONTINUOUS, CENTER, DASHED"
          },
          "lineweight": {
            "type": "integer",
            "description": "Lineweight in 1/100 mm (e.g. 50 = 0.50 mm), -1 = BYLAYER"
          },
          "tag": {
            "type": "string",
            "description": "Semantic tag for later reference as 'tag:<name>'"
          },
          "if_tag_exists": {
            "type": "string",
            "enum": [
              "error",
              "skip",
              "replace"
            ],
            "description": "Behaviour when an entity with this tag already exists (use 'skip' for idempotent replays)",
            "default": "error"
          }
        },
        "required": [
          "start",
          "end"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "add_linear_dim",
      "category": "annotate",
      "description": "Linear dimension between two points. orientation: horizontal | vertical | aligned | rotated. The dimension line is placed at 'base' or at 'offset' from the measured points.",
      "params": {
        "type": "object",
        "properties": {
          "p1": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "First extension line origin [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "p2": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Second extension line origin [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "orientation": {
            "type": "string",
            "enum": [
              "horizontal",
              "vertical",
              "aligned",
              "rotated"
            ],
            "description": "",
            "default": "horizontal"
          },
          "angle": {
            "type": "number",
            "description": "Measurement direction for orientation=rotated (degrees, counter-clockwise)",
            "default": 0.0
          },
          "offset": {
            "type": [
              "number",
              "string"
            ],
            "description": "Distance of the dimension line from the points (sign = side) (drawing units, or string with unit e.g. '8mm')",
            "default": 10.0
          },
          "base": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Explicit location of the dimension line [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "text": {
            "type": "string",
            "description": "Text override; '<>' stands for the measured value"
          },
          "text_height": {
            "type": [
              "number",
              "string"
            ],
            "description": "Override text height (drawing units, or string with unit e.g. '8mm')",
            "exclusiveMinimum": 0
          },
          "layer": {
            "type": "string",
            "description": "Layer name (created on the fly if missing)"
          },
          "color": {
            "type": "integer",
            "description": "ACI color (256 = BYLAYER)",
            "minimum": 0,
            "maximum": 257
          },
          "linetype": {
            "type": "string",
            "description": "Linetype name, e.g. CONTINUOUS, CENTER, DASHED"
          },
          "lineweight": {
            "type": "integer",
            "description": "Lineweight in 1/100 mm (e.g. 50 = 0.50 mm), -1 = BYLAYER"
          },
          "tag": {
            "type": "string",
            "description": "Semantic tag for later reference as 'tag:<name>'"
          },
          "if_tag_exists": {
            "type": "string",
            "enum": [
              "error",
              "skip",
              "replace"
            ],
            "description": "Behaviour when an entity with this tag already exists (use 'skip' for idempotent replays)",
            "default": "error"
          }
        },
        "required": [
          "p1",
          "p2"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "add_mtext",
      "category": "annotate",
      "description": "Multi-line text (MTEXT). Use '\\P' or newlines for line breaks.",
      "params": {
        "type": "object",
        "properties": {
          "text": {
            "type": "string",
            "description": "Text content"
          },
          "insert": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Top-left insert point [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "char_height": {
            "type": [
              "number",
              "string"
            ],
            "description": "Character height (drawing units, or string with unit e.g. '8mm')",
            "exclusiveMinimum": 0,
            "default": 2.5
          },
          "width": {
            "type": [
              "number",
              "string"
            ],
            "description": "Reference column width (optional) (drawing units, or string with unit e.g. '8mm')",
            "exclusiveMinimum": 0
          },
          "layer": {
            "type": "string",
            "description": "Layer name (created on the fly if missing)"
          },
          "color": {
            "type": "integer",
            "description": "ACI color (256 = BYLAYER)",
            "minimum": 0,
            "maximum": 257
          },
          "linetype": {
            "type": "string",
            "description": "Linetype name, e.g. CONTINUOUS, CENTER, DASHED"
          },
          "lineweight": {
            "type": "integer",
            "description": "Lineweight in 1/100 mm (e.g. 50 = 0.50 mm), -1 = BYLAYER"
          },
          "tag": {
            "type": "string",
            "description": "Semantic tag for later reference as 'tag:<name>'"
          },
          "if_tag_exists": {
            "type": "string",
            "enum": [
              "error",
              "skip",
              "replace"
            ],
            "description": "Behaviour when an entity with this tag already exists (use 'skip' for idempotent replays)",
            "default": "error"
          }
        },
        "required": [
          "text",
          "insert"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "add_point",
      "category": "draw",
      "description": "Draw a point entity.",
      "params": {
        "type": "object",
        "properties": {
          "location": {
            "type": "array",
            "items": {
              "type": [
                "number",
                "string"
              ]
            },
            "minItems": 2,
            "maxItems": 2,
            "description": "Location [x, y] (drawing units, or string with unit e.g. '8mm')"
          },
          "layer": {
            "type": "string",
            "description": "Layer name (created on the fly if missing)"
          },
          "color": {
            "type": "integer",
            "description": "ACI color (256 = BYLAYER)",
            "minimum": 0,
            "maximum": 257
          },
          "linetype": {
            "type": "string",
            "description": "Linetype name, e.g. CONTINUOUS, CENTER, DASHED"
          },
          "lineweight": {
            "type": "integer",
            "description": "Lineweight in 1/100 mm (e.g. 50 = 0.50 mm), -1 = BYLAYER"
          },
          "tag": {
            "type": "string",
            "description": "Semantic tag for later reference as 'tag:<name>'"
          },
          "if_tag_exists": {
            "type": "string",
            "enum": [
              "error",
              "skip",
              "replace"
            ],
            "description": "Behaviour when an entity with this tag already exists (use 'skip' for idempotent replays)",
            "default": "error"
          }
        },
        "required": [
          "location"
        ],
        "additionalProperties": false
      }
    },
    {
      "op": "add_polyline",
      "category": "draw",
      "description": "Draw a 2D polyline (LWPOLYLINE). Points may carry a bulge as third value (bulge = tan(arc_angle/4), positive = CCW arc to the next vertex).",
      "params": {
        "type": "object",
        "properties": {
          "points": {
            "type": "array",
            "items": {
              "type": "array"
            },
            "description": "Vertices list of [x, y] (or [x, y, bulge]) (drawing units, or string with unit e.g. '8mm')"
